        call(job, config, 'POST', 'check-runs', [name: metadata.CI_QUEUE_CONTEXT,
            head_sha: metadata.CI_QUEUE_COMMIT, external_id: identity(metadata), status: 'queued',
            output: [title: description, summary: description + '\n\nWaiting for a Jenkins executor.']])
    }

    void progress(def job, Map config, Map metadata, String description, boolean running) {
        if (!metadata.CI_QUEUE_CHECK_ID) return
        def check = find(job, config, metadata)
        if (check.status == 'completed' || check.output?.title == description) return
        def body = [output: [title: description, summary: description + '\n\n' +
            'Elapsed time and ETA are estimates from previous builds, not completed test counts.']]
        // The Pipeline transitions queued -> in_progress. Heartbeats never set
        // status, even on first allocation, so no late update can reopen a check.
        call(job, config, 'PATCH', "check-runs/${check.id}", body)
    }

    void finish(def job, Map config, Map metadata, String state, String description) {
        if (!metadata.CI_QUEUE_CHECK_ID) return
        def check = find(job, config, metadata)
        def title = check.output?.title ?: ''
        if (check.status == 'completed') {
