import groovy.json.JsonSlurperClassic
import groovy.transform.Field

@Field Map settings = [:]
@Field String pythonSource = ''

def configure(Map values) {
    settings = values
    pythonSource = readFile('jenkins_reporting.py')
    return this
}

def runReporter(String arguments, boolean authenticated = false) {
    // A Pipeline temporary directory is outside the candidate checkout. Python
    // isolated mode excludes candidate modules and PYTHONPATH from imports.
    def script = "${pwd(tmp: true)}/jenkins_reporting.py"
    writeFile file: script, text: pythonSource
    withEnv(["CI_REPORT_SCRIPT=${script}", "CI_REPORT_CONTEXT=${settings.context}",
             "CI_REPORT_PLATFORM=${settings.platform}", "CI_REPORT_PR=${settings.pr ?: ''}",
             "CI_REPORT_REF=${settings.ref ?: ''}", "CI_REPORT_COMMIT=${settings.commit ?: ''}",
             "CI_QUEUE_ID=${params.CI_QUEUE_ID ?: ''}",
             "CI_REPORT_MODE=${env.GKEYLL_CI_REPORT_MODE ?: 'auto'}"]) {
        def command = 'python3 -I "$CI_REPORT_SCRIPT" ' + arguments
        if (authenticated) {
            def mode = env.GKEYLL_CI_REPORT_MODE ?: 'auto'
            def checksCredential = mode == 'comments' ? settings.credential :
                (env.GKEYLL_CI_CHECKS_CREDENTIAL_ID?.trim() ?: settings.credential)
            def bindings = [usernamePassword(credentialsId: checksCredential,
                    usernameVariable: 'GITHUB_USERNAME', passwordVariable: 'GITHUB_TOKEN')]
            if (checksCredential != settings.credential) {
                bindings << usernamePassword(credentialsId: settings.credential,
                    usernameVariable: 'GITHUB_LEGACY_USERNAME', passwordVariable: 'GITHUB_LEGACY_TOKEN')
            }
            def bound = false
            try {
                withCredentials(bindings) { bound = true; sh command }
            } catch (err) {
                if (bound || checksCredential == settings.credential || mode == 'checks') throw err
                echo 'WARNING: Checks credential is unavailable; using the legacy reporting credential.'
                withEnv(['CI_REPORT_MODE=comments']) {
                    withCredentials([usernamePassword(credentialsId: settings.credential,
                            usernameVariable: 'GITHUB_USERNAME', passwordVariable: 'GITHUB_TOKEN')]) {
                        sh command
                    }
                }
            }
        } else {
            sh command
        }
    }
}

def publish(String result, String description = '', boolean detailed = false) {
    if (!(settings.commit ==~ /[0-9a-f]{40}/)) return ''
    withEnv(["CI_REPORT_RESULT=${result}", "CI_REPORT_DESCRIPTION=${description}"]) {
        if (detailed) {
            runReporter('build --platform "$CI_REPORT_PLATFORM" --context "$CI_REPORT_CONTEXT" ' +
                '--result "$CI_REPORT_RESULT" --pr "$CI_REPORT_PR" --output ci-report.md')
            description = readFile('ci-status-description.txt').trim()
        }
        def pluginPublished = false
        // The controller adapter pins the plugin to the accepted candidate SHA
        // and queue check ID. Never let it infer a SHA from the baseline/SCM.
        if (params.CI_QUEUE_CHECK_ID && params.CI_QUEUE_CHECKS_PLUGIN == 'true' &&
                (env.GKEYLL_CI_REPORT_MODE ?: 'auto') != 'comments') {
            try {
                def text = detailed ? new JsonSlurperClassic().parseText(readFile('ci-report.md.json'))[0] :
                    "${description}\n\n${fileExists('ci-stage-history.txt') ? readFile('ci-stage-history.txt') : ''}"
                def conclusion = [success: 'SUCCESS', failure: 'FAILURE', error: 'FAILURE',
                    cancelled: 'CANCELED', timed_out: 'TIME_OUT'][result] ?: 'NONE'
                publishChecks name: settings.context, status: result == 'pending' ? 'IN_PROGRESS' : 'COMPLETED',
                    conclusion: conclusion, title: description.take(250),
                    summary: "${settings.platform} build #${env.BUILD_NUMBER}; candidate `${settings.commit}`", text: text,
                    detailsURL: "https://github.com/gkeyllorg/gkeyll/runs/${params.CI_QUEUE_CHECK_ID}"
                pluginPublished = true
            } catch (err) {
                echo "WARNING: Checks plugin could not publish (${err.class.simpleName}); trying the Checks API."
            }
        }
        withEnv(["CI_REPORT_DESCRIPTION=${description}", "CI_VERIFY_PLUGIN=${pluginPublished}"]) {
            runReporter('update --platform "$CI_REPORT_PLATFORM" --context "$CI_REPORT_CONTEXT" ' +
                '--result "$CI_REPORT_RESULT" --commit "$CI_REPORT_COMMIT" --pr "$CI_REPORT_PR" ' +
                '--ref "$CI_REPORT_REF" --description "$CI_REPORT_DESCRIPTION" --mode "$CI_REPORT_MODE" ' +
                '--verify-plugin "$CI_VERIFY_PLUGIN"', true)
        }
    }
    return description
}

def progress(String description) {
    try { publish('pending', description) }
    catch (err) { echo "WARNING: CI progress could not be published (${err.class.simpleName}); the build continues." }
}

def ciStage(String name, Closure body) {
    env.CI_FAILURE_STAGE = name
    // Checkout deletes workspace files, so append history only once a candidate
    // commit has been recorded. The controller covers the initial queue/wait.
    if (settings.commit) {
        def history = fileExists('ci-stage-history.txt') ? readFile('ci-stage-history.txt') : ''
        writeFile file: 'ci-stage-history.txt', text: history + "${new Date().format("yyyy-MM-dd'T'HH:mm:ss'Z'", TimeZone.getTimeZone('UTC'))}  ${name}\n"
        progress("Running: ${name}.")
    }
    stage(name) { body.call() }
}

def writeCiFailureSummary(String result, String stageName, String message) {
    def compact = (message ?: 'unknown failure').replaceAll('[\\r\\n]+', ' ').trim().take(500)
    writeFile file: 'ci-failure-summary.txt', text: "result=${result}\nstage=${stageName ?: 'unknown'}\nmessage=${compact}\n"
}

def failureResult(def failure, String currentResult) {
    if (failure.toString().contains('FlowInterruptedException')) {
        if (failure.causes.any { it.class.simpleName == 'ExceededTimeout' }) return 'timed_out'
        return 'cancelled'
    }
    return currentResult == 'ABORTED' ? 'cancelled' : 'failure'
}

// Capture stdout/stderr and retain the original exit code. Never call these
// helpers with credential-bearing commands.
def loggedSh(String label, String script) {
    progress("Running: ${env.CI_FAILURE_STAGE ?: label} (${label}).")
    def quoted = "'" + script.replace("'", "'\"'\"'") + "'"
    withEnv(["CI_COMMAND_LOG=${env.WORKSPACE}/ci-command-logs/${label}.log"]) {
        sh """#!/bin/bash
            set -uo pipefail
            mkdir -p "\$WORKSPACE/ci-command-logs"
            bash ${script.startsWith('#!/bin/bash -l') ? '-l' : ''} -e -o pipefail -c ${quoted} 2>&1 | tee "\$CI_COMMAND_LOG"
            result=\$?
            printf '%s\\n' "\$result" > "\$CI_COMMAND_LOG.exit"
            exit "\$result"
        """
    }
}

def timeCommand(String metricFile, String command) {
    def logFile = metricFile.replaceFirst(/-seconds\.txt$/, '') + '.log'
    def detailFile = metricFile.replaceFirst(/[^\/]*$/, '') + 'ci-failure-detail.txt'
    def quoted = "'" + command.replace("'", "'\"'\"'") + "'"
    progress('Running: ' + metricFile.tokenize('/').last().replace('-seconds.txt', '').replace('-', ' ') + '.')
    sh """#!/bin/bash
        set -uo pipefail
        started=\$(date +%s)
        bash -e -o pipefail -c ${quoted} 2>&1 | tee '${logFile}'
        result=\$?
        printf '%s\\n' "\$result" > '${logFile}.exit'
        if [ "\$result" -ne 0 ]; then
            { printf 'Command: %s\\nFull log: %s (archived with the build)\\n' ${quoted} '${logFile}'; tail -n 100 '${logFile}'; } > '${detailFile}'
            exit "\$result"
        fi
        printf '%s\\n' "\$(( \$(date +%s) - started ))" > '${metricFile}'
    """
}

// Controller-side lifecycle, shared by the queue listener and its tests. The
// request closure supplies job-scoped credentials; no token is stored in state.
class GkeyllCheckLifecycle {
    final Closure request
    GkeyllCheckLifecycle(Closure request) { this.request = request }

    static String identity(Map metadata) {
        "gkeyll:${metadata.CI_QUEUE_CONTEXT}:queue:${metadata.CI_QUEUE_ID}"
    }

    def call(def job, Map config, String method, String path, Map body = null) {
        request(job, config + [credential: config.checksCredential ?: config.credential], method, path, body)
    }

    Map find(def job, Map config, Map metadata) {
        if (metadata.CI_QUEUE_CHECK_ID) {
            def check = call(job, config, 'GET', "check-runs/${metadata.CI_QUEUE_CHECK_ID}")
            if (check.head_sha != metadata.CI_QUEUE_COMMIT || check.name != metadata.CI_QUEUE_CONTEXT ||
                    check.external_id != identity(metadata)) throw new IOException('Check identity mismatch')
            return check
        }
        for (int page = 1; ; page++) {
            def checks = call(job, config, 'GET', "commits/${metadata.CI_QUEUE_COMMIT}/check-runs?filter=all&per_page=100&page=${page}&check_name=" +
                URLEncoder.encode(metadata.CI_QUEUE_CONTEXT, 'UTF-8')).check_runs
            def check = checks.find { it.head_sha == metadata.CI_QUEUE_COMMIT && it.name == metadata.CI_QUEUE_CONTEXT &&
                it.external_id == identity(metadata) }
            if (check || checks.size() < 100) return check
        }
    }

    Map queued(def job, Map config, Map metadata, String description) {
        def check = find(job, config, metadata)
        if (check) return check
        call(job, config, 'POST', 'check-runs', [name: metadata.CI_QUEUE_CONTEXT,
            head_sha: metadata.CI_QUEUE_COMMIT, external_id: identity(metadata), status: 'queued',
            output: [title: description, summary: description + '\n\nWaiting for a Jenkins executor.']])
    }

    void progress(def job, Map config, Map metadata, String description, boolean running) {
        if (!metadata.CI_QUEUE_CHECK_ID) return
        def check = find(job, config, metadata)
        if (check.status == 'completed' || check.output?.title == description) return
        def body = [output: [title: description, summary: description + '\n\n' +
            'Elapsed time and ETA are estimates from previous builds, not completed test counts.']]
        // The Pipeline transitions queued -> in_progress. Heartbeats never set
        // status, even on first allocation, so no late update can reopen a check.
