    "success": ":white_check_mark: passed",
    "failure": ":x: failed",
    "error": ":warning: errored or aborted",
    "pending": ":hourglass: running",
    "cancelled": ":stop_sign: cancelled",
    "timed_out": ":alarm_clock: timed out",
