                "~${Math.min(99, (int) (100.0 * elapsed / estimated))}%; est. remaining ${minutes(estimated - elapsed)}")
        String suffix = " (Jenkins queue #${id})."
        def activity = stage ? stage.take(36) + '; ' : ''
        "Gkeyll CI running: ${activity}started ${minutes(elapsed)} ago; ${progress}".take(140 - suffix.size()) + suffix
    }

