    prefix = MARKER_FORMAT.format(args.context + '/part-').split('" -->')[0]
    for comment in comments:
        old = comment.get('body') or ''
        if prefix in old and not any(m in old for m in markers):
            old_marker = re.search(re.escape(prefix) + r'\d+" -->', old)
            if old_marker:
                api('PATCH', update_url.format(comment['id']), token,
                    {'body': old_marker.group() + '\n\nDiagnostics for this part were cleared by the latest CI run; see the main report.'})



def check_identity(context, queue_id, build_id):
    """Queue IDs are controller-local; the machine's context makes them unique."""
    return 'gkeyll:{}:{}'.format(context, 'queue:' + queue_id if queue_id else 'build:' + build_id)


def find_check(args, token, name):
    url = '{}/repos/{}/commits/{}/check-runs?filter=all&per_page=100&check_name={}'.format(
        API, args.repo, args.commit, urllib.parse.quote(name, safe=''))
    while url:
        response, link = api('GET', url, token)
        for check in response.get('check_runs', []):
            if (check['name'] == name and check['head_sha'] == args.commit
                    and check.get('external_id') == args.external_id):
                return check
        url = next_link(link)
    return None


def check_conclusion(result):
    return {'success': 'success', 'failure': 'failure', 'error': 'failure',
            'cancelled': 'cancelled', 'timed_out': 'timed_out'}.get(result)


def check_output(args, text, page=0):
    title = args.description or status_description(args.result, args.stage, 0, [], [])
    summary = '**{}** — build #{}\n\nCandidate: `{}`\n\n{}'.format(
        args.platform, os.environ.get('BUILD_NUMBER', '?'), args.commit, title)
    diagnostics = read_text('ci-diagnostic-summary.json')
    if diagnostics:
        values = json.loads(diagnostics)
        summary += '\n\n**Diagnostics:** {} warning lines; {} new vs baseline; {} unclassified; {} error lines.'.format(
            values['warnings'], values['new_warnings'] if values['new_warnings'] is not None else 'unknown',
            values['unclassified_warnings'], values['errors'])
    if page:
        summary += '\n\nContinued diagnostics. See the primary check for the build result.'
    return {'title': byte_prefix(title, 250), 'summary': summary, 'text': text}


def update_check(args, token, name, output, conclusion=None):
    existing = find_check(args, token, name)
    # A late stage/heartbeat must never resurrect a terminal check.
    if existing and existing['status'] == 'completed' and conclusion is None:
        return existing
    payload = {'name': name, 'status': 'completed' if conclusion else 'in_progress',
               'external_id': args.external_id, 'output': output}
    if conclusion:
        payload['conclusion'] = conclusion
        payload['completed_at'] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    if existing:
        return api('PATCH', '{}/repos/{}/check-runs/{}'.format(API, args.repo, existing['id']),
                   token, payload)[0]
    payload['head_sha'] = args.commit
    return api('POST', '{}/repos/{}/check-runs'.format(API, args.repo), token, payload)[0]


def publish_checks(args, token):
    pages = [args.description + '\n\n' + read_text('ci-stage-history.txt')]
    if args.result != 'pending':
        pages = json.loads(read_text(args.report + '.json'))
    if not pages or any(not isinstance(p, str) or len(p.encode('utf-8')) > CHECK_LIMIT for p in pages):
        raise ValueError('Invalid or oversized Check report page')
    conclusion = check_conclusion(args.result)
    # Publish all diagnostic pages before marking the primary check complete.
    # This keeps a partial delivery visibly incomplete and makes retry safe.
    for index, page in enumerate(pages[1:], 2):
        update_check(args, token, args.context + ' / diagnostics {}'.format(index),
                     check_output(args, page, index), 'neutral')
    if args.verify_plugin == 'true':
        current = find_check(args, token, args.context)
        output = (current or {}).get('output') or {}
        if (current and current['status'] == ('completed' if conclusion else 'in_progress')
                and current.get('conclusion') == conclusion
                and output.get('title') == byte_prefix(args.description, 250)
                and output.get('text') == pages[0]):
            print('Verified GitHub Checks plugin delivery on the exact candidate SHA.')
            return current
        print('WARNING: Checks plugin delivery was not confirmed; using the Checks API.', file=sys.stderr)
    return update_check(args, token, args.context, check_output(args, pages[0]), conclusion)


def publish_legacy_status(args, token, description=None):
    state = {'cancelled': 'error', 'timed_out': 'error'}.get(args.result, args.result)
    description = description or args.description or status_description(args.result, args.stage, 0, [], [])
    if args.result == 'pending' and args.queue_id:
        suffix = ' (Jenkins queue #{}).'.format(args.queue_id)
        description = ('Gkeyll CI running: ' + description)[:140 - len(suffix)] + suffix
    return api('POST', '{}/repos/{}/statuses/{}'.format(API, args.repo, args.commit), token,
               {'state': state, 'context': args.context, 'description': description[:140]})[0]


def update_report(args):
    token = os.environ.get('GITHUB_TOKEN')
    if not token:
        raise ValueError('GITHUB_TOKEN is not set')
    if not re.fullmatch(r'[0-9a-f]{40}', args.commit):
        raise ValueError('Reporting requires the exact candidate commit SHA')
    args.external_id = check_identity(args.context, args.queue_id, args.build_id)
    legacy_token = os.environ.get('GITHUB_LEGACY_TOKEN') or token
    delivery = {'mode': args.mode, 'commit': args.commit, 'external_id': args.external_id,
                'checks': False, 'comment': False, 'status': False, 'errors': []}
    if args.mode != 'comments':
        try:
            check = publish_checks(args, token)
            delivery.update(checks=True, check_url=check.get('html_url', ''), check_id=check['id'])
            print('Published GitHub Check: ' + delivery['check_url'])
        except (RuntimeError, OSError, ValueError) as err:
            delivery['errors'].append('Checks: ' + str(err))
            print('WARNING: Checks publication failed: {}. Check the App installation and Checks write permission.'.format(err), file=sys.stderr)
    # Keep the established context working for branch protection during migration.
    try:
        publish_legacy_status(args, legacy_token)
        delivery['status'] = True
    except (RuntimeError, OSError) as err:
        delivery['errors'].append('Commit status: ' + str(err))
    if not delivery['checks'] and args.mode in ('auto', 'comments') and args.result != 'pending':
        try:
            publish_report(args, legacy_token)
            delivery['comment'] = True
            print('Used the backup GitHub comment reporter.')
        except (RuntimeError, OSError, ValueError, SystemExit) as err:
            delivery['errors'].append('Comment: ' + str(err))
    with open('ci-report-delivery.json', 'w', encoding='utf-8') as stream:
        json.dump(delivery, stream, indent=2)
    if delivery['errors']:
        print('Reporting diagnostics: ' + '; '.join(delivery['errors']), file=sys.stderr)
    if not delivery['checks'] and not delivery['comment'] and args.result != 'pending':
        raise RuntimeError('The detailed CI report could not be delivered; see ci-report-delivery.json')


