        heads['70'] = '70' * 20
        def checkJob = create(team, 'PR-70', "node('queue-test-runner') { echo 'CHECK_AGENT'; sleep time: 3600, unit: 'SECONDS' }")
        def checkItem = submit(checkJob, 600, [:])
        pending(checkItem, heads['70'], contexts[3])
        def checkMetadata = service.queuedParameters(checkItem.id, checkJob)
        def check = checkRuns[checkMetadata.CI_QUEUE_CHECK_ID.toLong()]
        assert check.status == 'queued'
        assert check.external_id == "gkeyll:${contexts[3]}:queue:${checkItem.id}"
        assert check.head_sha == heads['70']
        assert checkMetadata.CI_QUEUE_CHECKS_PLUGIN == 'true'
        assert jenkins.queue.cancel(jenkins.queue.getItem(checkItem.id))
        await('cancelled check') { check.status == 'completed' }
        assert check.conclusion == 'cancelled'
        passed('GitHub Check is queued before the executor, carries the accepted SHA, and closes on cancellation')

        heads['71'] = '71' * 20
        def earlyFailure = create(team, 'PR-71', "error 'failure before checkout'")
        def failedCheckRun = earlyFailure.scheduleBuild2(0).get(30, TimeUnit.SECONDS)
        def failedCheckId = service.parameters(failedCheckRun).CI_QUEUE_CHECK_ID.toLong()
        await('pre-checkout Check failure') { checkRuns[failedCheckId].status == 'completed' }
        assert checkRuns[failedCheckId].conclusion == 'failure'
        passed('early Pipeline errors complete the queued Check even without workspace reporting')

        controls.checksFailure = true
        heads['72'] = '72' * 20
        def noChecks = create(team, 'PR-72', "echo 'Checks permission failure must not stop tests'")
        assert noChecks.scheduleBuild2(0).get(30, TimeUnit.SECONDS).result == Result.SUCCESS
        await('legacy success after Checks failure') { statuses[heads['72'] + ':' + contexts[3]]?.state == 'success' }
        controls.remove('checksFailure')
        passed('Checks permission failures preserve builds and the legacy status fallback')

        heads['73'] = '73' * 20
        def timeoutJob = create(team, 'PR-73', "timeout(time: 1, unit: 'SECONDS') { sleep time: 30, unit: 'SECONDS' }")
        def timeoutRun = timeoutJob.scheduleBuild2(0).get(30, TimeUnit.SECONDS)
        def timeoutCheck = service.parameters(timeoutRun).CI_QUEUE_CHECK_ID.toLong()
        await('timeout check') { checkRuns[timeoutCheck].status == 'completed' }
        assert checkRuns[timeoutCheck].conclusion == 'timed_out'
        passed('Pipeline timeouts have their own timed_out Check conclusion')
        def publisher = io.jenkins.plugins.checks.api.ChecksPublisherFactory.fromRun(timeoutRun, hudson.model.TaskListener.NULL)
        assert publisher.class.name == 'GkeyllChecksPublisher'
        assert publisher.pinnedContext.headSha == heads['73']
        assert publisher.pinnedContext.getId(contexts[3]).get() == timeoutCheck
        assert publisher.pinnedContext.getRun().empty
        def detailBuilder = new io.jenkins.plugins.checks.api.ChecksDetails.ChecksDetailsBuilder()
        publisher.publish(detailBuilder.withName('Jenkins').build()) // Generic auto-notifications must be ignored.
        try {
            publisher.publish(detailBuilder.withName(contexts[3]).build())
            assert false : 'A missing App must signal fallback, not silently select another SCM'
        } catch (IllegalStateException expected) { }
        passed('native plugin factory pins the candidate and check ID, ignores generic notifications, and fails closed without an App')

        def smoke = create(jenkins, 'reporting-pipeline-smoke', '')
        smoke.definition = new CpsFlowDefinition('''
node('queue-test-runner') {
    deleteDir()
    writeFile file: 'jenkins_reporting.py', text: readFile(SOURCE + '/jenkins_reporting.py')
    def reporter = load(SOURCE + '/jenkins_reporting.groovy')
    reporter.configure([platform: 'personal', context: 'ci/smoke', credential: 'intentionally-missing', commit: 'a' * 40])
    reporter.ciStage('Smoke test') {
        reporter.loggedSh('candidate-smoke', "printf 'captured output\\n'")
        try { reporter.timeCommand('candidate-unit-build-seconds.txt', "printf 'example.c:3: error: deliberate test failure\\n'; exit 3") }
        catch (err) { echo 'EXPECTED_COMMAND_FAILURE' }
    }
    reporter.writeCiFailureSummary('failure', 'Smoke test', 'deliberate fixture failure')
    try { reporter.publish('failure', 'smoke failure', true) }
    catch (err) { echo 'EXPECTED_MISSING_CREDENTIAL' }
    assert readFile('candidate-unit-build.log.exit').trim() == '3'
    assert readFile('ci-report.md').contains('Failed at stage:** Smoke test')
    assert readFile('ci-report.md').contains('deliberate test failure')
    assert readFile('ci-stage-history.txt').contains('Smoke test')
    echo 'SHARED_REPORTING_SMOKE_PASSED'
}
'''.replace('SOURCE', groovy.json.JsonOutput.toJson(source.absolutePath)), true)
        def smokeRun = smoke.scheduleBuild2(0).get(60, TimeUnit.SECONDS)
        assert smokeRun.result == Result.SUCCESS : smokeRun.getLog(100).join('\n')
        passed('shared reporter runs in a real sandboxed Pipeline, retains command exits and builds diagnostic reports')

        ['personal', 'team_workstation', 'stellar_cpu', 'perlmutter_gpu'].each {
            shell.classLoader.parseClass(new File(source, "jenkinsfile.${it}"))
        }
        passed('all four Jenkinsfiles compile with Jenkins Groovy')
        new File(jenkins.rootDir, 'queue-test-result.txt').text = "PASS: ${checks} integration checks\n"
        println("PASS: ${checks} integration checks")
        jenkins.cleanUp()
        System.exit(0)
    } catch (Throwable failure) {
        failure.printStackTrace()
        new File(jenkins.rootDir, 'queue-test-result.txt').text = "FAIL: ${failure}\n"
        System.exit(1)
    }
}
        try {
            writeCiTimingSummary()
        } catch (err) {
            status = 'error'
            description = 'Personal CI timing summary failed.'
            if (!failureMessage) {
                failureMessage = err.toString()
                env.CI_FAILURE_STAGE = 'Write CI timing summary'
            } else {
                failureMessage += " | Timing summary also failed: ${err}"
            }
            currentBuild.result = 'FAILURE'
            echo "WARNING: could not write CI timings: ${err}"
        } finally {
            try {
                if (candidateDir) sh "ci/jenkins/baseline_cache.sh stage-candidate-artifacts '${gkeyllCiRoot}' '${cachePlatform}' '${commit}' '${env.WORKSPACE}' '${baselineCommit}'"
            } catch (err) {
                echo "WARNING: could not stage CI report artifacts: ${err}"
            }
            if (status != 'success') writeCiFailureSummary(status, env.CI_FAILURE_STAGE, failureMessage ?: description)
            // Best effort: a GitHub outage must not turn a passing build red.
            // Keep the full report locally if both GitHub transports are unavailable.
            def reportError = ''
            if (commit || candidatePr || candidateRef) {
                try {
                    def summaryLine = reporting.publish(status, description, true)
                    if (summaryLine) description = summaryLine.take(140)
                } catch (err) {
                    reportError = err.toString()
                    echo "WARNING: could not publish the GitHub CI report: ${reportError}"
                }
            }
            archiveArtifacts allowEmptyArchive: true, artifacts: 'ci-selection.txt,ci-baseline-preflight.txt,ci-baseline-cache.txt,ci-trusted-checker-commit.txt,ci-trusted-ci-commit.txt,ci-candidate-commit.txt,ci-baseline-commit.txt,*-seconds.txt,*-unit-results.txt,candidate-*.log,baseline-*.log,ci-failure-detail.txt,ci-report*.md,ci-report*.md.json,ci-report-delivery.json,ci-diagnostic-summary.json,ci-stage-history.txt,ci-command-logs/**,ci-timing-summary.txt,ci-regression-summary.txt,ci-parallel-regression-summary.txt,ci-failure-summary.txt,build/**/*.log,cuda-build/**/*.log,_baseline/build/**/*.log,_baseline/cuda-build/**/*.log,_baseline/gkylsoft/gkeyll-results/**/regressiondb,_baseline/gkylsoft/gkeyll-results/**/_rr_failures.txt,gkylsoft/gkeyll-results/**/regressiondb,gkylsoft/gkeyll-results/**/_rr_failures.txt'
            if (reportError) description = "${description} (report not posted)".take(140)
        }
        if (candidateDir && baselineCommit) {
            sh "ci/jenkins/baseline_cache.sh finalize-candidate '${gkeyllCiRoot}' '${cachePlatform}' '${commit}' '${baselineCommit}' '${status}' '${env.CI_FAILURE_STAGE ?: ''}' '${env.WORKSPACE}'"
        }
        deleteDir()
    }
}

