// Shared trusted Pipeline reporting. Load before the candidate checkout and
// keep the Python source in memory so the candidate cannot replace the publisher.
import groovy.transform.Field

@Field Map settings = [:]
@Field String pythonSource = ''
@Field String stageHistory = ''

def configure(Map values) {
    settings = values + [workspace: env.WORKSPACE]
    pythonSource = readFile('github_report.py')
    return this
}

def runReporter(String arguments, boolean authenticated = false) {
    // A Pipeline temporary directory is outside the candidate checkout. Python
    // isolated mode excludes candidate modules and PYTHONPATH from imports.
    def script = "${pwd(tmp: true)}/github_report.py"
    writeFile file: script, text: pythonSource
    withEnv(["CI_REPORT_SCRIPT=${script}", "CI_REPORT_CONTEXT=${settings.context}",
             "CI_REPORT_PLATFORM=${settings.platform}", "CI_REPORT_PR=${settings.pr ?: ''}",
             "CI_REPORT_REF=${settings.ref ?: ''}", "CI_REPORT_COMMIT=${settings.commit ?: ''}",
             "CI_QUEUE_ID=${params.CI_QUEUE_ID ?: ''}"]) {
        def command = 'python3 -I "$CI_REPORT_SCRIPT" ' + arguments
        if (authenticated) {
            withCredentials([usernamePassword(credentialsId: settings.credential,
                    usernameVariable: 'GITHUB_USERNAME', passwordVariable: 'GITHUB_TOKEN')]) {
                sh command
            }
        } else {
            sh command
        }
    }
}

def publish(String result, String description = '', boolean detailed = false) {
    // Commands can execute in cached candidate/baseline trees; report artifacts
    // always belong to the build workspace, never to one of those shared trees.
    dir(settings.workspace) {
        withEnv(["CI_REPORT_RESULT=${result}", "CI_REPORT_DESCRIPTION=${description}"]) {
            if (detailed) {
                writeFile file: 'ci-stage-history.txt', text: stageHistory
                runReporter('build --platform "$CI_REPORT_PLATFORM" --context "$CI_REPORT_CONTEXT" ' +
                    '--result "$CI_REPORT_RESULT" --pr "$CI_REPORT_PR" --output ci-report.md')
                description = readFile('ci-status-description.txt').trim()
            }
            // Keep a local report even if checkout failed before resolving a SHA.
            if (!(settings.commit ==~ /[0-9a-f]{40}/)) {
                echo 'WARNING: CI report retained locally; the candidate SHA is unavailable.'
                return
            }
            withEnv(["CI_REPORT_DESCRIPTION=${description}"]) {
                runReporter('update --platform "$CI_REPORT_PLATFORM" --context "$CI_REPORT_CONTEXT" ' +
                    '--result "$CI_REPORT_RESULT" --commit "$CI_REPORT_COMMIT" --pr "$CI_REPORT_PR" ' +
                    '--description "$CI_REPORT_DESCRIPTION"', true)
            }
        }
    }
    return description
}

def progress(String description) {
    try { publish('pending', description) }
    catch (err) { echo "WARNING: CI progress could not be published (${err.class.simpleName}); the build continues." }
}

def ciStage(String name, Closure body) {
    env.CI_FAILURE_STAGE = name
    // Keep history in Pipeline state as checkout deletes workspace files.
    stageHistory += "${new Date().format("yyyy-MM-dd'T'HH:mm:ss'Z'", TimeZone.getTimeZone('UTC'))}  ${name}\n"
    dir(settings.workspace) {
        writeFile file: 'ci-stage-history.txt', text: stageHistory
    }
    if (settings.commit) {
        progress("Running: ${name}.")
    }
    stage(name) { body.call() }
}

def writeCiFailureSummary(String result, String stageName, String message) {
    def compact = (message ?: 'unknown failure').replaceAll('[\\r\\n]+', ' ').trim().take(500)
    writeFile file: 'ci-failure-summary.txt', text: "result=${result}\nstage=${stageName ?: 'unknown'}\nmessage=${compact}\n"
}

def failureResult(def failure, String currentResult) {
    if (failure.toString().contains('FlowInterruptedException')) {
        if (failure.causes.any { it.class.simpleName == 'ExceededTimeout' }) return 'timed_out'
        return 'cancelled'
    }
    return currentResult == 'ABORTED' ? 'cancelled' : 'failure'
}

// Capture stdout/stderr and retain the original exit code. Never call these
// helpers with credential-bearing commands.
def loggedSh(String label, String script) {

    void cancelSuperseded(Map candidate, String head) {
        String description = "Gkeyll CI cancelled while queued; superseded by ${head.take(12)}."
        Queue.withLock({
            def live = Jenkins.get().queue.getItem(candidate.id as long)
            if (live == null || live instanceof Queue.LeftItem) return
            // Recheck under the scheduling lock: never cancel a node that has started.
            def current = candidate.run ? parameters(candidate.run) : queuedParameters(live.id, live.task)
            if (current.CI_QUEUE_COMMIT != candidate.values.CI_QUEUE_COMMIT || current.CI_QUEUE_STARTED == 'true') return
            if (candidate.run) {
                def update = new ParametersAction([
                    new StringParameterValue('CI_QUEUE_CANCEL_DESCRIPTION', description)], INTERNAL)
                candidate.run.addOrReplaceAction(candidate.run.getAction(ParametersAction).merge(update))
            } else {
                def record = states.get(candidate.id)
                if (record != null) record.cancelDescription = description
            }
            if (Jenkins.get().queue.cancel(live)) LOG.info("Queue #${candidate.id}: ${description}")
        } as Runnable)
    }

    void completed(Run run) {
        def metadata = parameters(run)
        if (metadata.CI_QUEUE_ID != run.queueId.toString()) return
        workers.submit({
            def state = run.result == Result.SUCCESS ? 'success' :
                (run.result in [Result.FAILURE, Result.UNSTABLE] ? 'failure' : 'cancelled')
            if (run.getAction(jenkins.model.InterruptedBuildAction)?.causes?.any { it.class.simpleName == 'ExceededTimeout' }) state = 'timed_out'
            def description = metadata.CI_QUEUE_CANCEL_DESCRIPTION ?:
                (state == 'timed_out' ? 'Gkeyll CI timed out.' :
                 run.result == Result.ABORTED && metadata.CI_QUEUE_STARTED != 'true'
                    ? 'Gkeyll CI cancelled while queued.' : "Gkeyll CI finished: ${run.result}.")
            finish(run.parent, metadata, run.queueId, state, description)
            progressBase.remove(run.queueId)
        } as Runnable)
    }

    void finish(Job job, Map metadata, long id, String state, String description) {
        // Cancellation must follow an in-flight position POST, never precede it.
        synchronized (statusLock(id)) {
            finishStatus(job, metadata, id, state in ['cancelled', 'timed_out'] ? 'error' : state, description)
        }
    }

    void finishStatus(Job job, Map metadata, long id, String state, String description) {
        if (metadata.CI_QUEUE_ID != id.toString() || !(metadata.CI_QUEUE_COMMIT ==~ /[0-9a-f]{40}/)) return
        def config = configuration(job)
        if (!config?.credential) return
        try {
            def current = request(job, config, 'GET', "commits/${metadata.CI_QUEUE_COMMIT}/status?per_page=100")
                .statuses.find { it.context == metadata.CI_QUEUE_CONTEXT }
            // Preserve the Pipeline's detailed terminal status and another run's newer status.
            if (!ownsQueuedStatus(current, id) && !ownsRunningStatus(current, id)) return
            // The Pipeline can publish its detailed result while a progress POST
            // is in flight. Recover that result rather than leaving stale pending
            // or replacing its diagnostics with our generic completion message.
            if (ownsRunningStatus(current, id) && progressBase.containsKey(id)) {
                def history = request(job, config, 'GET', "commits/${metadata.CI_QUEUE_COMMIT}/statuses?per_page=100")
                def terminal = history.find { it.context == metadata.CI_QUEUE_CONTEXT &&
                    (it.id as long) > progressBase[id] && it.state in ['success', 'failure', 'error'] }
                if (terminal) {
                    def body = [state: terminal.state, context: metadata.CI_QUEUE_CONTEXT,
                        description: terminal.description]
                    if (terminal.target_url) body.target_url = terminal.target_url
                    request(job, config, 'POST', "statuses/${metadata.CI_QUEUE_COMMIT}", body)
                    return

